import{_ as i,a0 as p,w as r,s as a,I as l,x as e,a1 as o,A as s,ao as m}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse(`{"title":"Linux用户應知應會的7個‘ls’命令的獨特技巧 | LCTT x X-CMD","titleTemplate":false,"description":"Linux用户應知應會的7個‘ls’命令的獨特技巧 | LCTT (201505) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux用户應知應會的7個‘ls’命令的獨特技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux用户應知應會的7個‘ls’命令的獨特技巧 | LCTT (201505) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201505/20150324 7 Quirky' ls' Command Tricks Every Linux User Should Know","title":"Linux用户應知應會的7個‘ls’命令的獨特技巧","tag":"201505","desc":""},"relativePath":"201505/20150324 7 Quirky' ls' Command Tricks Every Linux User Should Know.md","filePath":"[post].md"}`),d={name:"201505/20150324 7 Quirky' ls' Command Tricks Every Linux User Should Know.md"};function c(u,t,w,g,f,h){const n=p("Link");return r(),a("div",null,[t[16]||(t[16]=l("h1",{id:"linux用户應知應會的7個-ls-命令的獨特技巧",tabindex:"-1"},[e("Linux用户應知應會的7個‘ls’命令的獨特技巧 "),l("a",{class:"header-anchor",href:"#linux用户應知應會的7個-ls-命令的獨特技巧","aria-label":"Permalink to “Linux用户應知應會的7個‘ls’命令的獨特技巧”"},"​")],-1)),t[17]||(t[17]=l("p",null,"在前面我們系列報道的兩篇文章中，我們已經涵蓋了關於‘ls’命令的絕大多數內容。本文時‘ls命令’系列的最後一部分。如果你還沒有讀過該系列的其它兩篇文章，你可以訪問下面的鏈接。",-1)),l("ul",null,[l("li",null,[o(n,{href:"https://linux.cn/article-5109-1.html"},{default:s(()=>[...t[0]||(t[0]=[e("Linux中的15個基本‘ls’命令示例",-1)])]),_:1})]),l("li",null,[o(n,{href:"https://linux.cn/article-5349-1.html"},{default:s(()=>[...t[1]||(t[1]=[e("15 個‘ls’命令的面試問題（一）",-1)])]),_:1})]),l("li",null,[o(n,{href:"https://linux.cn/article-5350-1.html"},{default:s(()=>[...t[2]||(t[2]=[e("10 個‘ls’命令面試的問題（二）",-1)])]),_:1})])]),t[18]||(t[18]=m(`<p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/ls-command-tricks.jpg" alt="7 Quirky ls Command Tricks"></p><p><em>7個ls命令獨特技巧</em></p><h3 id="_1-以各種時間格式附帶時間戳列出目錄中的內容" tabindex="-1">1. 以各種時間格式附帶時間戳列出目錄中的內容 <a class="header-anchor" href="#_1-以各種時間格式附帶時間戳列出目錄中的內容" aria-label="Permalink to “1. 以各種時間格式附帶時間戳列出目錄中的內容”">​</a></h3><p>要以時間格式列出目錄內容，我們需要選擇以下兩種方法中的任何一種。</p><pre><code># ls -l –time-style=[STYLE]               (方法 A)
</code></pre><p><strong>注意</strong> - 上面的開關<code>--time</code>的格式必須和<code>-l</code>開關同時使用，否則達不到目的。</p><pre><code># ls -full-time                           (方法 B)
</code></pre><p>可以用以下任何一個選項替換<code>[STYLE]</code>。</p><pre><code>full-iso
long-iso
iso
locale
+%H:%M:%S:%D
</code></pre><p><strong>注意</strong> - 在上面行中，H（時），M（分），S（秒），D（日）的順序可以任意調整。此外，你只需選擇那些相關的選項，而不是所有選項。例如，<code>ls -l --time-style=+%H</code>將只顯示小時。<code>ls -l --time-style=+%H:%M:%D</code>將顯示小時、分鐘和日。</p><pre><code># ls -l --time-style=full-iso
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/ls-Command-Full-Time-Style.gif" alt="ls Command Full Time Style"></p><p><em>ls命令的完整 ISO時間格式</em></p><pre><code># ls -l --time-style=long-iso
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Long-Time-Listing-Format.gif" alt="Long Time Style Listing"></p><p><em>長時間格式列表</em></p><pre><code># ls -l --time-style=iso
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Local-Time-Style-Listing.gif" alt="Time Style Listing"></p><p><em>時間格式列表</em></p><pre><code># ls -l --time-style=locale
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Hour-Mintue-Time-Style-Listing.gif" alt="Locale Time Style Listing"></p><p><em>本地時間格式列表</em></p><pre><code># ls -l --time-style=+%H:%M:%S:%D
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Full-Time-Style-Listing.gif" alt="Date and Time Style Listing"></p><p><em>日期和時間格式列表</em></p><pre><code># ls --full-time
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Full-Style-Time-Listing.gif" alt="Full Style Time Listing"></p><p><em>完整格式時間列表</em></p><h3 id="_2-以多種格式列出目錄內容-如以逗號分隔、水平格式、長格式、垂直格式、交叉格式等列出。" tabindex="-1">2. 以多種格式列出目錄內容，如以逗號分隔、水平格式、長格式、垂直格式、交叉格式等列出。 <a class="header-anchor" href="#_2-以多種格式列出目錄內容-如以逗號分隔、水平格式、長格式、垂直格式、交叉格式等列出。" aria-label="Permalink to “2. 以多種格式列出目錄內容，如以逗號分隔、水平格式、長格式、垂直格式、交叉格式等列出。”">​</a></h3><p>目錄內容可以用以下建議的ls命令各種格式列出：</p><pre><code># ls --format=across		# 交叉
# ls --format=comma			# 逗號
# ls --format=horizontal	# 水平
# ls --format=long			# 長格式
# ls --format=single-column	# 單欄
# ls --format=verbose		# 詳情
# ls --format=vertical		# 垂直
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/ls-command-Listing-Formats.gif" alt="Listing Formats of ls Command"></p><p><em>ls命令的列出格式</em></p><h3 id="_3-使用ls命令為目錄內容輸出結果添加像-這樣的指示符。" tabindex="-1">3. 使用ls命令為目錄內容輸出結果添加像（/=@|）這樣的指示符。 <a class="header-anchor" href="#_3-使用ls命令為目錄內容輸出結果添加像-這樣的指示符。" aria-label="Permalink to “3. 使用ls命令為目錄內容輸出結果添加像（/=@|）這樣的指示符。”">​</a></h3><p>帶有<code>-p</code>選項的ls命令將實現該目的。它會根據文件類型添加上面這些指示符其中之一。</p><pre><code># ls -p
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Append-Indicators.gif" alt="Append Indicators to Content"></p><p><em>添加指示符到內容</em></p><h3 id="_4-根據擴展名、大小、時間和版本對目錄內容排序。" tabindex="-1">4. 根據擴展名、大小、時間和版本對目錄內容排序。 <a class="header-anchor" href="#_4-根據擴展名、大小、時間和版本對目錄內容排序。" aria-label="Permalink to “4. 根據擴展名、大小、時間和版本對目錄內容排序。”">​</a></h3><p>我們可以使用<code>--extension</code>選項來按照擴展名對輸出結果排序，<code>--size</code>擴展選項按照大小排序，<code>-t</code>擴展選項按照時間排序，<code>-v</code>擴展選項對版本排序。</p><p>我們也可以使用<code>--none</code>選項，它會以常規方式輸出結果而不會進行排序。</p><pre><code># ls --sort=extension
# ls --sort=size
# ls --sort=time
# ls --sort=version
# ls --sort=none
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Sort-Content-by-Extensions.gif" alt="Sort Listing of Content by Options"></p><p><em>通過選項對內容排序列出</em></p><h3 id="_5-使用ls命令打印目錄中各個項的數字uid和gid。" tabindex="-1">5. 使用ls命令打印目錄中各個項的數字UID和GID。 <a class="header-anchor" href="#_5-使用ls命令打印目錄中各個項的數字uid和gid。" aria-label="Permalink to “5. 使用ls命令打印目錄中各個項的數字UID和GID。”">​</a></h3><p>上面的環境可以通過使用帶有-n標識的ls命令來實現。</p><pre><code># ls -n
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/Print-UID-GID-of-Contents.gif" alt="Print Listing of Content by UID and GID"></p><p><em>通過UID和GID對打印內容列表</em></p><h3 id="_6-標準輸出結果中打印目錄內容中比默認指定的更多欄目。" tabindex="-1">6. 標準輸出結果中打印目錄內容中比默認指定的更多欄目。 <a class="header-anchor" href="#_6-標準輸出結果中打印目錄內容中比默認指定的更多欄目。" aria-label="Permalink to “6. 標準輸出結果中打印目錄內容中比默認指定的更多欄目。”">​</a></h3><p>好吧，ls命令根據屏幕大小自動輸出目錄內容。</p><p>然而，我們可以手動分配屏幕寬度的值和出現的欄目的控制數。這可以通過使用‘<code>--width</code>’開關實現。</p><pre><code># ls --width 80
# ls --width 100
# ls --width 150
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Content-By-More-Column.gif" alt="List Content Based on Window Sizes"></p><p><em>根據窗口大小列出內容</em></p><p><strong>注意</strong>： 你可以試驗你可以給width標識傳遞什麼值。</p><h3 id="_7-通過ls命令為列出的目錄內容手動指定的製表符大小而不是默認的8。" tabindex="-1">7. 通過ls命令為列出的目錄內容手動指定的製表符大小而不是默認的8。 <a class="header-anchor" href="#_7-通過ls命令為列出的目錄內容手動指定的製表符大小而不是默認的8。" aria-label="Permalink to “7. 通過ls命令為列出的目錄內容手動指定的製表符大小而不是默認的8。”">​</a></h3><pre><code># ls --tabsize=[value]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2015/03/List-Content-by-Table-Size.gif" alt="List Content by Table Size"></p><p><em>按表尺寸列出內容</em></p><p><strong>注意</strong>： 指定<code>[Value]</code>的數值。</p><p>到目前為止，都講完了。保持連線，我們會推出下一篇文章。別忘了在下面的評論中為我們提供有價值的反饋。為我們點贊並分享，幫我們推廣。</p><hr>`,63)),l("p",null,[t[4]||(t[4]=e("via: ",-1)),o(n,{href:"http://www.tecmint.com/linux-ls-command-tricks/"},{default:s(()=>[...t[3]||(t[3]=[e("http://www.tecmint.com/linux-ls-command-tricks/",-1)])]),_:1})]),l("p",null,[t[8]||(t[8]=e("作者：",-1)),o(n,{href:"http://www.tecmint.com/author/avishek/"},{default:s(()=>[...t[5]||(t[5]=[e("Avishek Kumar",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),o(n,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[6]||(t[6]=[e("GOLinux",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),o(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[7]||(t[7]=[e("wxy",-1)])]),_:1})]),l("p",null,[t[13]||(t[13]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),o(n,{href:"http://linux.cn/"},{default:s(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const y=i(d,[["render",c]]);export{T as __pageData,y as default};
